using System.Globalization;
using System.Xml.Linq;
using Avalonia;
using Avalonia.Controls;
using Avalonia.Markup.Xaml;
using Avalonia.Media;

namespace Themes.Tests;

/// <summary>
/// Checks each ported palette against the vendored WPF original: every key, with the same colour,
/// opacity and gradient. The palettes are generated by scripts/port-palettes.sh.
/// </summary>
[TestClass]
public sealed class PaletteParityTests
{
    private static readonly XNamespace Xaml = "http://schemas.microsoft.com/winfx/2006/xaml";

    [TestMethod]
    [DataRow(Theme.Light, "LightColors")]
    [DataRow(Theme.Blue, "BlueColors")]
    [DataRow(Theme.Dark, "DarkColors")]
    public void Palette_MatchesUpstream(Theme theme, string name)
    {
        string path = Path.Combine(RepoPaths.UpstreamFrameworkSrc, "Themes", "Resources", "Colors", name + ".xaml");
        List<XElement> expected = XDocument.Load(path).Root!.Elements()
            .Where(e => e.Attribute(Xaml + "Key") != null)
            .ToList();
        Assert.IsTrue(expected.Count > 300, $"{name}: only {expected.Count} resources found upstream");

        HeadlessSession.Run(() =>
        {
            var dictionary = (ResourceDictionary)AvaloniaXamlLoader.Load(
                new Uri(ThemeResourceHelper.GetColorDictionaryUri(theme)));
            Assert.AreEqual(expected.Count, dictionary.Count, $"{name}: number of resources");

            foreach (XElement element in expected)
            {
                string key = element.Attribute(Xaml + "Key")!.Value;
                Assert.IsTrue(dictionary.TryGetValue(key, out object? value), $"{name}: {key} is missing");
                string where = $"{name}: {key}";
                switch (element.Name.LocalName)
                {
                    case "Color":
                        Assert.AreEqual(Color.Parse(element.Value.Trim()), (Color)value!, where);
                        break;
                    case "SolidColorBrush":
                        var brush = (ISolidColorBrush)value!;
                        Assert.AreEqual(Color.Parse(element.Attribute("Color")!.Value), brush.Color, where);
                        Assert.AreEqual(ParseDouble(element.Attribute("Opacity")?.Value ?? "1"), brush.Opacity, where);
                        break;
                    case "LinearGradientBrush":
                        AssertGradient(element, (ILinearGradientBrush)value!, where);
                        break;
                    default:
                        Assert.Fail($"{where}: unexpected resource type {element.Name.LocalName}");
                        break;
                }
            }
        });
    }

    private static void AssertGradient(XElement element, ILinearGradientBrush brush, string where)
    {
        // WPF gradient points are fractions of the element's bounds (MappingMode RelativeToBoundingBox).
        Assert.AreEqual(ParseRelativePoint(element.Attribute("StartPoint")?.Value ?? "0,0"), brush.StartPoint, $"{where}: StartPoint");
        Assert.AreEqual(ParseRelativePoint(element.Attribute("EndPoint")?.Value ?? "1,1"), brush.EndPoint, $"{where}: EndPoint");

        List<XElement> stops = element.Elements().Where(e => e.Name.LocalName == "GradientStop").ToList();
        Assert.AreEqual(stops.Count, brush.GradientStops.Count, $"{where}: gradient stops");
        for (int i = 0; i < stops.Count; i++)
        {
            Assert.AreEqual(Color.Parse(stops[i].Attribute("Color")!.Value), brush.GradientStops[i].Color, $"{where}: stop {i} colour");
            Assert.AreEqual(ParseDouble(stops[i].Attribute("Offset")!.Value), brush.GradientStops[i].Offset, $"{where}: stop {i} offset");
        }
    }

    private static RelativePoint ParseRelativePoint(string value)
    {
        string[] parts = value.Split(',');
        return new RelativePoint(ParseDouble(parts[0]), ParseDouble(parts[1]), RelativeUnit.Relative);
    }

    private static double ParseDouble(string value) => double.Parse(value, CultureInfo.InvariantCulture);
}
